effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float l = gmLum(c);
  vec3 base = mix(c, vec3(l), desat);
  vec3 bc = clamp((base - 0.5) * contrast + 0.5 + lift, 0.0, 1.0);
  bc = bc * bc * (3.0 - 2.0 * bc);            // soft S-curve
  vec3 col = mix(c, bc, mixAmt);
  gl_FragColor = vec4(col * a, a);
}
